<script>const wStore=@json(route('warnings-store')),wUpdate=@json(route('warnings-update','__ID__')),wStatus=@json(route('warnings-status','__ID__'));function wd(x){return x?JSON.parse(atob(x)):{}}function openWarning(mode,x){let f=document.getElementById('warningForm'),d=wd(x);f.reset();f.action=wStore;document.getElementById('warningMethod').innerHTML='';document.getElementById('warningTitle').textContent=mode==='edit'?'Edit Warning':'Add New Warning';['employee_id','warning_by','warning_type','subject','severity','warning_date','description','expiry_date','improvement_goals','improvement_start_date','improvement_end_date','status'].forEach(k=>f.elements[k].value=d[k]|| (k==='status'?'Draft':''));f.querySelector('[type=checkbox]').checked=!!d.has_improvement_plan;if(mode==='edit'){f.action=wUpdate.replace('__ID__',d.id);document.getElementById('warningMethod').innerHTML='<input type="hidden" name="_method" value="PUT">'}}function viewWarning(x){let d=wd(x),m=document.getElementById('warningView');m.querySelector('[data-wv=employee]').textContent=d.employee_name||'—';m.querySelector('[data-wv=badges]').innerHTML='<span class="warning-badge severity-'+d.severity.toLowerCase()+'">'+d.severity+'</span> <span class="warning-badge">'+d.status+'</span>';let v={subject:d.subject,type:d.warning_type,manager:d.manager,date:d.warning_date,expiry:d.expiry_date,plan:d.has_improvement_plan?'Yes':'No',description:d.description,goals:d.improvement_goals};Object.keys(v).forEach(k=>m.querySelector('[data-wv='+k+']').textContent=v[k]||'—')}function openWarningStatus(id,s){let f=document.getElementById('warningStatusForm');f.action=wStatus.replace('__ID__',id);f.elements.status.value=s}document.addEventListener('DOMContentLoaded',()=>{let f=document.getElementById('warningForm'),required={employee_id:'Employee',warning_by:'Warning By',warning_type:'Warning Type',subject:'Subject',severity:'Severity',warning_date:'Warning Date'};f.onsubmit=e=>{f.querySelectorAll('.warning-error').forEach(x=>x.remove());let first;Object.entries(required).forEach(([k,n])=>{let x=f.elements[k];if(!x.value){x.insertAdjacentHTML('afterend','<div class="warning-error">'+n+' is required</div>');first=first||x}});if(first){e.preventDefault();first.focus()}};document.querySelectorAll('.warning-delete').forEach(form=>form.onsubmit=e=>{if(form.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete warning',text:'Are you sure? This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',icon:'warning'}).then(r=>{if(r.isConfirmed){form.dataset.ok=1;form.submit()}})})});</script>
<script>
document.addEventListener('DOMContentLoaded',function(){var icons={view:'<svg viewBox="0 0 24 24"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></svg>',edit:'<svg viewBox="0 0 24 24"><path d="M12 20H5a1 1 0 0 1-1-1v-7"/><path d="m16.5 3.5 4 4L11 17l-5 1 1-5Z"/></svg>',status:'<svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 0-2.3 5.7"/><path d="M20 4v7h-7"/></svg>',remove:'<svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/></svg>'};document.querySelectorAll('.warning-table tbody tr').forEach(function(row){var box=row.querySelector('td:last-child .d-flex');if(!box)return;var buttons=box.querySelectorAll(':scope > button.warning-action');if(buttons[0]){buttons[0].innerHTML=icons.view;buttons[0].title='View'}if(buttons[1]){buttons[1].innerHTML=icons.edit;buttons[1].title='Edit'}if(buttons[2]){buttons[2].innerHTML=icons.status;buttons[2].title='Change Status'}var remove=box.querySelector('form.warning-delete button');if(remove){remove.innerHTML=icons.remove;remove.title='Delete'}})});
</script>
